const researchRelocationFilesystemControls="from pathlib import Path\nimport hashlib, json, shutil\n\nRESEARCH_SCREENSHOT_NAMES = {'hold-collide-browser': ['chromium-390-hero.png', 'chromium-390-figure.png', 'chromium-390-research.png', 'chromium-390-carousel.png', 'chromium-820-hero.png', 'chromium-820-figure.png', 'chromium-820-research.png', 'chromium-820-carousel.png', 'chromium-1440-hero.png', 'chromium-1440-figure.png', 'chromium-1440-research.png', 'chromium-1440-carousel.png', 'webkit-390-hero.png', 'webkit-390-figure.png', 'webkit-390-research.png', 'webkit-390-carousel.png', 'webkit-820-hero.png', 'webkit-820-figure.png', 'webkit-820-research.png', 'webkit-820-carousel.png', 'webkit-1440-hero.png', 'webkit-1440-figure.png', 'webkit-1440-research.png', 'webkit-1440-carousel.png'], 'durable-organization-browser': ['chromium-390-hero.png', 'chromium-390-figure.png', 'chromium-820-hero.png', 'chromium-820-figure.png', 'chromium-1440-hero.png', 'chromium-1440-figure.png', 'webkit-390-hero.png', 'webkit-390-figure.png', 'webkit-820-hero.png', 'webkit-820-figure.png', 'webkit-1440-hero.png', 'webkit-1440-figure.png']}\nPNG_SIGNATURE = b'\\x89PNG\\r\\n\\x1a\\n'\n\ndef relocate_research_artifacts(source_root, destination_root):\n    assert source_root.is_dir() and not source_root.is_symlink(), 'Original QA output root must be a real directory'\n    assert {p.name for p in source_root.iterdir()} == set(RESEARCH_SCREENSHOT_NAMES), 'Only the two completed research QA directories may exist'\n    assert not destination_root.exists() and not destination_root.is_symlink(), 'Never overwrite an existing artifact destination'\n    assert destination_root.parent.is_dir() and not destination_root.parent.is_symlink(), 'Existing report artifact parent must be a real directory'\n    manifest = []\n    for folder, expected in RESEARCH_SCREENSHOT_NAMES.items():\n        directory = source_root / folder\n        assert directory.is_dir() and not directory.is_symlink(), 'Research QA directory must be real'\n        assert {p.name for p in directory.iterdir()} == set(expected), 'Every exact authored screenshot and no unexpected file must exist'\n        for name in expected:\n            image = directory / name\n            assert image.is_file() and not image.is_symlink(), 'Only regular authored PNG files may move'\n            data = image.read_bytes()\n            assert len(data) > 32 and data.startswith(PNG_SIGNATURE) and data[12:16] == b'IHDR', 'Every moved artifact must be a PNG image'\n            manifest.append({'path': folder + '/' + name, 'bytes': len(data), 'sha256': hashlib.sha256(data).hexdigest()})\n    assert len(manifest) == 36 and len({row['path'] for row in manifest}) == 36, 'Exact36 authored screenshots required'\n    destination_root.mkdir()\n    for folder in RESEARCH_SCREENSHOT_NAMES:\n        shutil.move(str(source_root / folder), str(destination_root / folder))\n    for row in manifest:\n        image = destination_root / row['path']\n        assert image.is_file() and not image.is_symlink(), 'Moved PNG remains a regular file'\n        data = image.read_bytes()\n        assert len(data) == row['bytes'] and hashlib.sha256(data).hexdigest() == row['sha256'], 'Every screenshot byte and SHA256 must survive relocation'\n    source_root.rmdir()\n    return manifest\n\nimport base64, tempfile\npositive_count = negative_count = 0\npng = base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aX1EAAAAASUVORK5CYII=')\n\ndef prepared(parent):\n    source = parent / 'tmp'\n    source.mkdir()\n    for folder, names in RESEARCH_SCREENSHOT_NAMES.items():\n        directory = source / folder\n        directory.mkdir()\n        for name in names:\n            (directory / name).write_bytes(png)\n    artifact_parent = parent / 'artifact'\n    artifact_parent.mkdir()\n    return source, artifact_parent / 'research-publication-screenshots'\n\nwith tempfile.TemporaryDirectory(prefix='coherence-relocation-positive-') as temporary:\n    source, destination = prepared(Path(temporary))\n    rows = relocate_research_artifacts(source, destination)\n    assert len(rows) == 36 and not source.exists()\n    assert {p.relative_to(destination).as_posix() for p in destination.rglob('*') if p.is_file()} == {row['path'] for row in rows}\n    assert all((destination / row['path']).read_bytes() == png for row in rows)\n    positive_count += 1\n\nnegative_names = ['missing screenshot', 'unexpected file', 'unexpected nested directory', 'symlink image', 'symlink source directory', 'symlink source root', 'invalid PNG bytes', 'existing destination', 'symlink destination', 'symlink artifact parent', 'unknown sibling source output', 'changed bytes during relocation']\nfor kind in range(len(negative_names)):\n    with tempfile.TemporaryDirectory(prefix='coherence-relocation-negative-') as temporary:\n        parent = Path(temporary)\n        source, destination = prepared(parent)\n        first = source / 'hold-collide-browser' / RESEARCH_SCREENSHOT_NAMES['hold-collide-browser'][0]\n        real_move = shutil.move\n        if kind == 0: first.unlink()\n        elif kind == 1: (first.parent / 'UNKNOWN.png').write_bytes(png)\n        elif kind == 2: (first.parent / 'unknown-directory').mkdir()\n        elif kind == 3:\n            first.unlink(); first.symlink_to(parent / 'other.png'); (parent / 'other.png').write_bytes(png)\n        elif kind == 4:\n            directory = source / 'hold-collide-browser'; directory.rename(parent / 'elsewhere'); directory.symlink_to(parent / 'elsewhere', target_is_directory=True)\n        elif kind == 5:\n            source.rename(parent / 'elsewhere'); source.symlink_to(parent / 'elsewhere', target_is_directory=True)\n        elif kind == 6: first.write_bytes(b'NOT A PNG')\n        elif kind == 7: destination.mkdir()\n        elif kind == 8: destination.symlink_to(parent / 'missing-destination', target_is_directory=True)\n        elif kind == 9:\n            destination.parent.rename(parent / 'real-artifact'); (parent / 'artifact').symlink_to(parent / 'real-artifact', target_is_directory=True)\n        elif kind == 10: (source / 'unknown-output').mkdir()\n        elif kind == 11:\n            def corrupt_move(before, after):\n                result = real_move(before, after)\n                image = next(Path(after).glob('*.png'))\n                image.write_bytes(image.read_bytes() + b'CHANGED')\n                return result\n            shutil.move = corrupt_move\n        try:\n            try: relocate_research_artifacts(source, destination)\n            except AssertionError: negative_count += 1\n            else: raise AssertionError('Relocation accepted ' + negative_names[kind])\n        finally: shutil.move = real_move\nassert positive_count == 1 and negative_count == 12\nprint(json.dumps({'ok': True, 'positiveCount': positive_count, 'negativeCount': negative_count, 'files': 36}))\n";
